engine.urParseAiJson:
function urParseAiJson(raw) {
  if (!raw) return null;
  var s = String(raw).trim();
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/```$/, "").trim();
  try { return JSON.parse(s); } catch (e) { /* fall through */ }
  var startObj = s.indexOf("{");
  var startArr = s.indexOf("[");
  var start = -1;
  if (startObj === -1) start = startArr;
  else if (startArr === -1) start = startObj;
  else start = Math.min(startObj, startArr);
  if (start === -1) return null;
  var open = s[start];
  var close = open === "{" ? "}" : "]";
  var depth = 0, inStr = false, esc = false;
  for (var i = start; i < s.length; i++) {
    var c = s[i];
    if (esc) { esc = false; continue; }
    if (c === "\\") { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === open) depth++;
    else if (c === close) {
      depth--;
      if (depth === 0) {
        try { return JSON.parse(s.substring(start, i + 1)); }
        catch (e) { return null; }
      }
    }
  }
  return null;
}

// Build the Usage Risks LLM prompt fresh — improved over v2's prompt:
// explicit JSON shape, ELI_IDX_<n> id contract, list-of-anchors format,
// Colgate-protective framing. Caller passes the indexed paragraph JSON
// (the {id, text}[] shape produced by getPromptAnchors) as `text`.

engine.urNormalize:
function urNormalize(data) {
  var out = data;
  if (Array.isArray(out)) {
    out = { items: out };
  } else if (out && typeof out === "object" && !out.items) {
    var foundKey = Object.keys(out).filter(function (k) {
      return Array.isArray(out[k]);
    })[0];
    out.items = foundKey ? out[foundKey] : [];
  } else if (!out || typeof out !== "object") {
    out = { items: [] };
  }
  function _strip(s) {
    if (s == null) return s;
    return String(s)
      .replace(/\[INSERTED(?: by [^:\]]+)?:\s*([\s\S]*?)\]/g, "$1")
      .replace(/\[MOVED TO(?: by [^:\]]+)?:\s*([\s\S]*?)\]/g, "$1")
      .replace(/\[DELETED(?: by [^:\]]+)?:\s*[\s\S]*?\]/g, "")
      .replace(/\[MOVED FROM(?: by [^:\]]+)?:\s*[\s\S]*?\]/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }
  if (Array.isArray(out.items) && out.items.length) {
    out.items.forEach(function (item) {
      if (!item || typeof item !== "object") return;
      ["topic", "detail", "impact", "watchout", "suggestion", "quote"].forEach(function (k) {
        if (item[k]) item[k] = _strip(item[k]);
      });
      // Coerce id → canonical ELI_IDX_<n>.
      var rawId = item.id || item.paragraph_id || item.paragraphId || item.anchor || "";
      rawId = String(rawId).trim().replace(/^_+/, "");
      var normalized = "";
      if (rawId.indexOf("ELI_IDX_") === 0) normalized = rawId;
      else {
        var m = rawId.match(/(\d+)$/);
        if (m) normalized = "ELI_IDX_" + m[1];
      }
      item.id = normalized || null;
      // 2026-05-16: severity dropped — every finding is by definition
      // something that COULD negatively impact Colgate, so the badge
      // added noise without separating signal. Strip any severity field
      // the AI might still emit so it can't leak into the UI.
      delete item.severity;
      // category — always Usage for this tool.
      item.category = "Usage";
      // text — the verbatim quote is what legal_risks's _fixClause needs.
      item.text = item.text || item.quote || "";
      // fix_suggestion — alias suggestion → fix_suggestion so the
      // dispatch into legal_risks.fixClause sees the field it expects.
      item.fix_suggestion = item.fix_suggestion || item.suggestion || "";
    });
  } else if (out) {
    out.items = out.items || [];
  }
  return out;
}

// Engine entry — orchestrates the full pipeline. Caller (init.js) passes
// the JSON-stringified indexed-paragraphs blob as `text` (same shape
// legal_risks uses, produced by eli.host.helpers.getPromptAnchors), and
// the providers map. Returns Promise<{items, overview, provenance, ...}>.
//
// Self-contained — every helper this function uses is INLINED below.

engine.analyze:
function analyze(input, providers) {
  input = input || {};
  providers = providers || {};
  var text = String(input.text || "");
  var docHash = input.docHash || null;

  var ai = providers.ai || (window.eli && window.eli.ai);
  if (!ai || typeof ai.complete !== "function") {
    return Promise.reject(new Error("eli.ai provider missing"));
  }

  // Inline: urBuildPrompt
  var prompt = [
    "You are a Commercial IT Analyst at Colgate-Palmolive. Your job is to",
    "extract a COMPLETE operational profile of what Colgate is buying — every",
    "constraint, limit, deadline, threshold, or rule that governs HOW Colgate",
    "uses the product/service or interacts with the vendor.",
    "",
    "CRITICAL RULES — PROTECT COLGATE:",
    "1. PERSPECTIVE: You work FOR Colgate. Every finding must be something",
    "   that COULD NEGATIVELY IMPACT Colgate — create cost, risk, restriction,",
    "   obligation, lock-in, exposure, or operational headache. Skip ANYTHING",
    "   that is neutral or favorable to Colgate (e.g., vendor commits to",
    "   99.9% uptime — Colgate's benefit, NOT a usage risk; vendor gives",
    "   Colgate 90 days termination notice — Colgate's right, NOT a constraint).",
    "2. IGNORE obligations placed solely on the vendor / counterparty. Only",
    "   flag rules COLGATE must follow or limits that apply to COLGATE.",
    "3. Examples of items that DO impact Colgate negatively (flag these):",
    "   API rate limits / overage fees, seat caps, notice periods Colgate must",
    "   give, auto-renewal lock-in, termination-for-convenience deadlines",
    "   Colgate must hit, audit response windows, data residency restrictions,",
    "   usage reporting cadence, MFA mandates Colgate must implement, browser/OS",
    "   compatibility limits, certificate rotation Colgate must maintain,",
    "   breach notification deadlines on Colgate, throttling rules, change-",
    "   control procedures Colgate must follow, vendor-mandated tools/integrations.",
    "4. DO NOT flag legal-style risks (indemnity, IP, liability caps,",
    "   warranties) — those belong to a different scan.",
    "5. The document is provided below as a JSON array of paragraphs, each",
    "   with an `id` (format `ELI_IDX_<n>`) and `text`. When you find a",
    "   constraint, return the EXACT id of the paragraph where it lives.",
    "   This id is how Colgate's ELI tooling jumps to and edits the clause.",
    "",
    "OUTPUT — JSON object with one key `items`, value is an array of:",
    "{",
    '  "id":         "ELI_IDX_<n>   — REQUIRED — exact paragraph id from input",',
    '  "topic":      "Short topic name (e.g. \\"API Rate Limit\\", \\"Auto-Renewal\\")",',
    '  "detail":     "The specific constraint, in plain language",',
    '  "impact":     "Operational impact on Colgate (1-2 sentences)",',
    '  "watchout":   "The single biggest danger if Colgate misses or misreads this",',
    '  "suggestion": "Concrete mitigation: re-negotiate cap, pre-purchase, add notice cushion, request carve-out, etc.",',
    '  "quote":      "Verbatim short snippet from the paragraph (<= 220 chars)"',
    "}",
    "",
    "If no usage constraints exist, return: { \"items\": [], \"overview\":",
    "\"No operational constraints detected.\" }. Otherwise include a 1-2",
    "sentence `overview` field summarizing the operational profile.",
    "",
    "Be concise — no preamble, no markdown code fence, JSON only.",
    "",
    "PARAGRAPHS:",
    text.substring(0, 500000),
  ].join("\n");

  // Prefer completeJSON when available (structured output mode), fall
  // back to complete + manual JSON parse. The latter is what every v3
  // tool uses today — keeps the bundler simple.
  var aiPromise;
  if (typeof ai.completeJSON === "function") {
    aiPromise = ai.completeJSON(prompt, null, { signal: input.signal, sanitize: false });
  } else {
    aiPromise = ai.complete(prompt, { signal: input.signal, sanitize: false }).then(function (raw) {
      // Inline: urParseAiJson
      if (!raw) return null;
      var s = String(raw).trim().replace(/^```(?:json)?\s*/i, "").replace(/```$/, "").trim();
      try { return JSON.parse(s); } catch (e) { /* fall through */ }
      var startObj = s.indexOf("{");
      var startArr = s.indexOf("[");
      var start = -1;
      if (startObj === -1) start = startArr;
      else if (startArr === -1) start = startObj;
      else start = Math.min(startObj, startArr);
      if (start === -1) return null;
      var open = s[start];
      var close = open === "{" ? "}" : "]";
      var depth = 0, inStr = false, esc = false;
      for (var i = start; i < s.length; i++) {
        var c = s[i];
        if (esc) { esc = false; continue; }
        if (c === "\\") { esc = true; continue; }
        if (c === '"') { inStr = !inStr; continue; }
        if (inStr) continue;
        if (c === open) depth++;
        else if (c === close) {
          depth--;
          if (depth === 0) {
            try { return JSON.parse(s.substring(start, i + 1)); }
            catch (e2) { return null; }
          }
        }
      }
      return null;
    });
  }

  return aiPromise.then(function (data) {
    // Inline: urNormalize
    var out = data;
    if (Array.isArray(out)) {
      out = { items: out };
    } else if (out && typeof out === "object" && !out.items) {
      var foundKey = Object.keys(out).filter(function (k) {
        return Array.isArray(out[k]);
      })[0];
      out.items = foundKey ? out[foundKey] : [];
    } else if (!out || typeof out !== "object") {
      out = { items: [] };
    }
    function _strip(s) {
      if (s == null) return s;
      return String(s)
        .replace(/\[INSERTED(?: by [^:\]]+)?:\s*([\s\S]*?)\]/g, "$1")
        .replace(/\[MOVED TO(?: by [^:\]]+)?:\s*([\s\S]*?)\]/g, "$1")
        .replace(/\[DELETED(?: by [^:\]]+)?:\s*[\s\S]*?\]/g, "")
        .replace(/\[MOVED FROM(?: by [^:\]]+)?:\s*[\s\S]*?\]/g, "")
        .replace(/\s+/g, " ")
        .trim();
    }
    if (Array.isArray(out.items) && out.items.length) {
      out.items.forEach(function (item) {
        if (!item || typeof item !== "object") return;
        ["topic", "detail", "impact", "watchout", "suggestion", "quote"].forEach(function (k) {
          if (item[k]) item[k] = _strip(item[k]);
        });
        var rawId = item.id || item.paragraph_id || item.paragraphId || item.anchor || "";
        rawId = String(rawId).trim().replace(/^_+/, "");
        var normalized = "";
        if (rawId.indexOf("ELI_IDX_") === 0) normalized = rawId;
        else {
          var m = rawId.match(/(\d+)$/);
          if (m) normalized = "ELI_IDX_" + m[1];
        }
        item.id = normalized || null;
        delete item.severity; // 2026-05-16: severity tagging removed (see urNormalize).
        item.category = "Usage";
        item.text = item.text || item.quote || "";
        item.fix_suggestion = item.fix_suggestion || item.suggestion || "";
      });
    }

    var items = out.items || [];
    var overview = out.overview ||
      (items.length
        ? "Operational profile: " + items.length + " constraint" + (items.length === 1 ? "" : "s") + " extracted."
        : "No operational constraints detected.");

    // Enrich with structural-map section info (same pass legal_risks
    // uses). Decorates each item with `_sectionNumber / _sectionTitle /
    // _sectionAnchor` so the view's section badge can show the real
    // header and jump-to-section. Falls back silently when the kernel
    // doesn't expose readStructuralMap.
    var hostP = providers.host || (window.eli && window.eli.host);
    var baseResult = {
      items: items,
      overview: overview,
      provenance: {
        kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
        toolVersion: "v3.0",
        docHash: docHash,
        timestamp: Date.now(),
      },
    };
    if (!hostP || typeof hostP.readStructuralMap !== "function" || !items.length) {
      return baseResult;
    }
    return hostP.readStructuralMap({ prefix: "ELI_IDX_" }).then(function (smap) {
      try {
        var byParaIdx = (smap && smap.byParagraphIdx) || {};
        items.forEach(function (item) {
          if (!item || !item.id) return;
          var mm = String(item.id).match(/_(\d+)$/);
          if (!mm) return;
          var paraIdx = parseInt(mm[1], 10);
          if (!isFinite(paraIdx)) return;
          var sec = (typeof smap.getSection === "function") ? smap.getSection(paraIdx) : null;
          var headRow = null;
          var thisRow = byParaIdx[paraIdx];
          if (thisRow && thisRow.isHeader) headRow = thisRow;
          else {
            for (var pj = paraIdx - 1; pj >= 0; pj--) {
              var c = byParaIdx[pj];
              if (c && c.isHeader) { headRow = c; break; }
            }
          }
          if (sec) {
            item._sectionNumber = sec.number || "";
            item._sectionTitle = sec.title || "";
            if (headRow && headRow.anchor) item._sectionAnchor = headRow.anchor;
          } else {
            var fallback = (thisRow && thisRow.belongsTo) || "Document Introduction";
            item._sectionNumber = "";
            item._sectionTitle = fallback;
            item._sectionBelongsToOnly = true;
          }
        });
      } catch (_) { /* decorative — never fail */ }
      return baseResult;
    }).catch(function () { return baseResult; });
  });
}

view.renderProgressOverlay:
function renderProgressOverlay(cb) {
