  function close() { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); }
  return { close: close };
}

// Main results renderer. opts:
//   mount      HTMLElement — where to paint (defaults to _eli3_dashboard_root)
//   data       {items, overview, ...}
//   onHome     () → close → return to dashboard
//   onLocate   (item) → Promise — jump to clause in doc
//   onFix      (item) → void   — hand to legal_risks's surgical editor
//   onIgnore   (item) → void   — DOM remove + toast
//
// Self-contained: _e (escape) and _renderCard are nested helpers — the
// kernel's evalBundle isolates each top-level function so sibling
// top-level fns from this file are NOT in scope at runtime.

view.renderResults:
function renderResults(opts) {
  function _e(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Per-card render — nested so it shares _e + the closure with the
  // outer renderer (no cross-top-level reference).
  function _renderCard(item, idx) {
    var card = document.createElement("div");
    card.className = "_eli3_ur_card";
    card.setAttribute("data-idx", String(idx));

    // 2026-05-16: severity tagging removed. Every finding represents a
    // potential negative impact on Colgate, so a low/medium/high split
    // added visual noise without separating signal. Card uses the single
    // cyan accent from CSS.

    // Section badge (top-right). Uses the structural-map enrichment the
    // engine added (item._sectionNumber + _sectionTitle + _sectionAnchor).
    var sectionBadgeHtml = "";
    var secNumRaw = String(item._sectionNumber || "").trim();
    var secTitle = String(item._sectionTitle || "").trim();
    var hasSection = !!(secNumRaw || secTitle);
    if (hasSection) {
      var isUnnumbered = !secNumRaw || secNumRaw === "[Unnumbered]";
      var isBelongsToOnly = !!item._sectionBelongsToOnly;
      var label;
      if (isBelongsToOnly) {
        var bt = secTitle.length > 30 ? secTitle.slice(0, 27).trim() + "…" : secTitle;
        label = bt;
      } else if (isUnnumbered) {
        label = "§ Unnumbered";
      } else {
        var titleShort = secTitle.length > 24 ? secTitle.slice(0, 21).trim() + "…" : secTitle;
        label = "§ " + secNumRaw + (titleShort ? " " + titleShort : "");
      }
      var canJump = !!(item._sectionAnchor && !isBelongsToOnly);
      if (canJump) {
        sectionBadgeHtml =
          '<button type="button" class="_eli3_ur_card_section _eli3_ur_card_section_jump" ' +
            'data-action="jump-section" data-section-anchor="' + _e(item._sectionAnchor) + '" ' +
            'title="Jump to section header">' +
            _e(label) +
          '</button>';
      } else {
        sectionBadgeHtml = '<span class="_eli3_ur_card_section">' + _e(label) + '</span>';
      }
    }

    // Topic — required. Fallback so cards never paint empty.
    var topic = String(item.topic || "").trim() || ("Constraint #" + (idx + 1));

    // Detail / impact / watchout / suggestion / quote — each only renders
    // when the AI provided non-empty content.
    var detailHtml = item.detail
      ? '<div class="_eli3_ur_card_detail">' + _e(item.detail) + '</div>'
      : '';
    var impactHtml = item.impact
      ? '<div class="_eli3_ur_card_impact">' +
          '<span class="_eli3_ur_card_impact_eyebrow">IMPACT</span>' +
          '<div class="_eli3_ur_card_impact_body">' + _e(item.impact) + '</div>' +
        '</div>'
      : '';
    var watchoutHtml = item.watchout
      ? '<div class="_eli3_ur_card_watchout">' +
          '<span class="_eli3_ur_card_watchout_icon">🚨</span>' +
          '<div class="_eli3_ur_card_watchout_body"><strong>WATCHOUT:</strong> ' + _e(item.watchout) + '</div>' +
        '</div>'
      : '';
    var suggestionHtml = item.suggestion
      ? '<div class="_eli3_ur_card_suggestion">' +
          '<span class="_eli3_ur_card_suggestion_icon">💡</span>' +
          '<div class="_eli3_ur_card_suggestion_body"><strong>SUGGESTION:</strong> ' + _e(item.suggestion) + '</div>' +
        '</div>'
      : '';
    var quote = String(item.quote || item.text || "").trim();
    var quoteHtml = quote
      ? '<div class="_eli3_ur_card_quote">"' + _e(quote.length > 240 ? quote.slice(0, 237) + "…" : quote) + '"</div>'
      : '';

    card.innerHTML =
      '<div class="_eli3_ur_card_eyebrow">' +
        '<span class="_eli3_ur_card_eyebrow_icon">📡</span>' +
        '<span class="_eli3_ur_card_eyebrow_label">USAGE CONSTRAINT</span>' +
        sectionBadgeHtml +
      '</div>' +
      '<div class="_eli3_ur_card_body">' +
        '<div class="_eli3_ur_card_head">' +
          '<span class="_eli3_ur_card_num">' + (idx + 1) + '.</span>' +
          '<span class="_eli3_ur_card_topic">' + _e(topic) + '</span>' +
        '</div>' +
        detailHtml +
        impactHtml +
        watchoutHtml +
        suggestionHtml +
        quoteHtml +
        '<div class="_eli3_ur_card_actions">' +
          '<button type="button" class="_eli3_ur_btn _eli3_ur_btn_locate" data-action="locate" data-idx="' + idx + '">' +
            '<span class="_eli3_ur_btn_icon">📍</span> LOCATE' +
          '</button>' +
          '<button type="button" class="_eli3_ur_btn _eli3_ur_btn_fix" data-action="fix" data-idx="' + idx + '">' +
            '<span class="_eli3_ur_btn_icon">🔧</span> FIX' +
          '</button>' +
          '<button type="button" class="_eli3_ur_btn _eli3_ur_btn_ignore" data-action="ignore" data-idx="' + idx + '" title="Dismiss this constraint">' +
            '<span class="_eli3_ur_btn_icon">⊘</span> IGNORE' +
          '</button>' +
        '</div>' +
      '</div>';

    return card;
  }

  opts = opts || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return null;
  var data = opts.data || { items: [] };
  var items = Array.isArray(data.items) ? data.items : [];
  var onHome = opts.onHome || function () {};
  var onLocate = opts.onLocate || function () {};
  var onFix = opts.onFix || function () {};
  var onIgnore = opts.onIgnore || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ur_results";
  root.setAttribute("data-eli-view", "usage-risks");

  // ─── Banner — use the canonical eli.ui.banner primitive ──────────
  var bannerEl;
  var hasBannerPrim = window.eli && window.eli.ui && typeof window.eli.ui.banner === "function";
  if (hasBannerPrim) {
    bannerEl = window.eli.ui.banner({
      eyebrow: items.length === 0 ? "ALL CLEAR" : "OPERATIONAL PROFILE",
      title: "Usage Risks",
      count: items.length === 0 ? "📡" : items.length,
      countLabel: items.length === 0 ? "scan" : (items.length === 1 ? "constraint" : "constraints"),
    });
  } else {
    bannerEl = document.createElement("div");
    bannerEl.className = "_eli3_ur_banner_fallback";
    bannerEl.style.cssText =
      "background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);" +
      "border-bottom: 3px solid #c9a227;" +
      "padding: 14px 16px; display: flex; justify-content: space-between;" +
      "align-items: center; margin-bottom: 18px;";
    bannerEl.innerHTML =
      '<div>' +
        '<div style="font: 700 8px/1 Inter, sans-serif; color:#8fa6c7; text-transform:uppercase; letter-spacing:2px; margin-bottom:3px;">' +
          (items.length === 0 ? "ALL CLEAR" : "OPERATIONAL PROFILE") +
        '</div>' +
        '<div style="font: 400 17px/1 Georgia, serif; color:#fff;">Usage Risks</div>' +
      '</div>' +
      '<div style="background:rgba(255,255,255,0.12); border:1px solid rgba(255,255,255,0.25); padding:6px 14px; min-width:44px; text-align:center;">' +
        '<div style="font: 800 22px/1 Inter, sans-serif; color:#fff;">' + (items.length === 0 ? "📡" : items.length) + '</div>' +
        '<div style="font: 700 8px/1 Inter, sans-serif; color:rgba(255,255,255,0.55); text-transform:uppercase; margin-top:2px;">' +
          (items.length === 0 ? "scan" : (items.length === 1 ? "constraint" : "constraints")) +
        '</div>' +
      '</div>';
  }
  root.appendChild(bannerEl);

  // ─── Overview strip ───────────────────────────────────────────────
  var overviewText = String(data.overview || "").trim();
  if (overviewText) {
    var ovEl = document.createElement("div");
    ovEl.className = "_eli3_ur_overview";
    ovEl.innerHTML =
      '<div class="_eli3_ur_overview_label">📡 Operational Profile</div>' +
      '<div class="_eli3_ur_overview_body">' + _e(overviewText) + '</div>';
    root.appendChild(ovEl);
  }

  // ─── Empty state ─────────────────────────────────────────────────
  if (!items.length) {
    var emptyEl = document.createElement("div");
    emptyEl.className = "_eli3_ur_empty";
    emptyEl.innerHTML =
      '<div class="_eli3_ur_empty_icon">📡</div>' +
      '<div class="_eli3_ur_empty_title">No usage constraints detected</div>' +
      '<div class="_eli3_ur_empty_desc">' +
        'No seat caps, rate limits, SLAs, notice periods, audit terms, or other ' +
        'operational rules were extracted. Either the agreement is unusually ' +
        'open, or operational clauses live somewhere the scan missed — check ' +
        'attachments, schedules, or exhibits separately.' +
      '</div>' +
      '<button type="button" class="_eli3_ur_empty_home">← Back to dashboard</button>';
    root.appendChild(emptyEl);
    mount.appendChild(root);
    var homeBtn0 = emptyEl.querySelector("._eli3_ur_empty_home");
    if (homeBtn0) homeBtn0.onclick = onHome;
    return { refresh: function () {} };
  }

  // ─── Card grid ────────────────────────────────────────────────────
  var cardsHost = document.createElement("div");
  cardsHost.className = "_eli3_ur_cards";
  items.forEach(function (item, idx) {
    cardsHost.appendChild(_renderCard(item, idx));
  });
  root.appendChild(cardsHost);

  // ─── Footer ───────────────────────────────────────────────────────
  var homeBar = document.createElement("div");
  homeBar.className = "_eli3_ur_homebar";
  homeBar.innerHTML = '<button type="button" class="_eli3_ur_home_btn">← HOME</button>';
  root.appendChild(homeBar);

  mount.appendChild(root);

  // ─── Wire interactions ───────────────────────────────────────────
  Array.prototype.forEach.call(root.querySelectorAll("[data-action]"), function (btn) {
    btn.onclick = function (ev) {
      ev.stopPropagation();
      var idx = Number(btn.getAttribute("data-idx"));
      var item = items[idx];
      var action = btn.getAttribute("data-action");
      if (action === "jump-section") {
        var anchor = btn.getAttribute("data-section-anchor");
        if (anchor && window.eli && window.eli.host &&
            typeof window.eli.host.highlightAnchor === "function") {
          window.eli.host.highlightAnchor(anchor).catch(function () {});
        }
        return;
      }
      if (!item) return;
      if (action === "locate") {
        var orig = btn.innerHTML;
        btn.innerHTML = "Locating…";
        Promise.resolve().then(function () { return onLocate(item); })
          .then(function () { btn.innerHTML = orig; })
          .catch(function () { btn.innerHTML = orig; });
      } else if (action === "fix") {
        onFix(item, btn);
      } else if (action === "ignore") {
        onIgnore(item, btn);
        var card = root.querySelector('._eli3_ur_card[data-idx="' + idx + '"]');
        if (card && card.parentNode) card.parentNode.removeChild(card);
      }
    };
  });

  var homeBtn = root.querySelector("._eli3_ur_home_btn");
  if (homeBtn) homeBtn.onclick = onHome;

  return { refresh: function () {} };
}

